package localchat;
import java.nio.file.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.regex.*;
/** Explicit private root configuration; read-only, bounded discovery, no model or document reads. */
final class ProjectLocations {
 record Root(String factory,String path){}
 record Match(Root root,String folder){String label(){String name=folder.isEmpty()?root.path:folder;String factory=root.factory.isBlank()?I18n.text("Fabrica de confirmat"):"MBS "+Character.toUpperCase(root.factory.charAt(0))+root.factory.substring(1);String label=factory+" — "+name+(folder.isEmpty()?" ("+I18n.text("Folder de proiect neconfirmat")+")":"");return label;}}
 record Result(String project,List<Match> matches,List<Root> available,List<String> unavailable){
  List<Match> choices(){var choices=new ArrayList<Match>(matches);for(Root root:available)if(matches.stream().noneMatch(m->m.root.path.equalsIgnoreCase(root.path)))choices.add(new Match(root,""));return List.copyOf(choices);}
  String json(){return Json.write(Json.obj("project",project,"matches",matches.stream().map(m->Json.obj("factory",m.root.factory,"path",m.root.path,"folder",m.folder)).toList(),"available",available.stream().map(r->Json.obj("factory",r.factory,"path",r.path)).toList(),"unavailable",unavailable));}
 }
 static List<Root> roots(Object config){var result=new ArrayList<Root>();Object value=Json.get(config,"projectRoots");if(value instanceof List<?> list)for(Object item:list){String path=Json.str(item,"path"),factory=Objects.toString(Json.str(item,"factory"),"");if(path!=null&&!path.isBlank()&&path.length()<1000&&factory.length()<80&&result.size()<12&&!result.stream().anyMatch(r->r.path.equalsIgnoreCase(path)))result.add(new Root(factory,path));}return List.copyOf(result);}
 static Result parse(String raw){Object data=Json.parse(raw);String project=Json.str(data,"project");if(project==null||!project.matches("[0-9]{6}"))throw new IllegalArgumentException("project");var available=new ArrayList<Root>();Object a=Json.get(data,"available");if(a instanceof List<?> list)for(Object entry:list){var roots=roots(Json.obj("projectRoots",List.of(entry)));available.addAll(roots);if(available.size()>12)throw new IllegalArgumentException("roots");}var matches=new ArrayList<Match>();Object m=Json.get(data,"matches");if(m instanceof List<?> list)for(Object entry:list){List<Root> root=roots(Json.obj("projectRoots",List.of(entry)));String folder=Json.str(entry,"folder");if(root.size()!=1||folder==null||folder.length()>2000||matches.size()>=100)throw new IllegalArgumentException("match");matches.add(new Match(root.get(0),folder));}var unavailable=new ArrayList<String>();Object u=Json.get(data,"unavailable");if(u instanceof List<?> list)for(Object entry:list)if(entry instanceof String path&&path.length()<1000&&unavailable.size()<12)unavailable.add(path);return new Result(project,List.copyOf(matches),List.copyOf(available),List.copyOf(unavailable));}
 static String project(String message,Path folder,String previous){
  Matcher explicit=Pattern.compile("(?i)(?:proiect(?:ul)?|project|projekt|proje)[^0-9\\r\\n]{0,25}([0-9]{6})(?![0-9])").matcher(message);if(explicit.find())return explicit.group(1);
  if(message.toLowerCase(Locale.ROOT).matches("(?s).*(productie|pdfcontrol|productie-projecten).*")){Matcher number=Pattern.compile("(?<![0-9])[0-9]{6}(?![0-9])").matcher(message);if(number.find())return number.group();}
  if(folder!=null&&folder.getFileName()!=null&&folder.getFileName().toString().matches("[0-9]{6}"))return folder.getFileName().toString();return previous!=null&&previous.matches("[0-9]{6}")?previous:"";
 }
 private static final ExecutorService POOL=Executors.newFixedThreadPool(4,r->{Thread t=new Thread(r,"project-root-read");t.setDaemon(true);return t;});
 private record Scan(Root root,List<Match> matches){}
 static Result scan(String project,List<Root> roots,long timeoutMillis){
  List<Future<Scan>> tasks=new ArrayList<>();for(Root root:roots)tasks.add(POOL.submit(()->{Path path=Path.of(root.path).toRealPath();List<Match> found=new ArrayList<>();int count=0;try(var entries=Files.newDirectoryStream(path)){for(Path entry:entries){if(++count>50000)throw new IOException("Inventory limit");String name=entry.getFileName().toString();if(name.matches(Pattern.quote(project)+"(?:$|[^0-9].*)")&&Files.isDirectory(entry,LinkOption.NOFOLLOW_LINKS)&&!Files.isSymbolicLink(entry)&&entry.toRealPath().startsWith(path)){found.add(new Match(root,entry.toRealPath().toString()));if(found.size()>50)throw new IOException("Match limit");}}}return new Scan(root,found);}));
  long deadline=System.nanoTime()+TimeUnit.MILLISECONDS.toNanos(timeoutMillis);var found=new ArrayList<Match>();var available=new ArrayList<Root>();var unavailable=new ArrayList<String>();Set<String> canonical=new HashSet<>();
  for(int i=0;i<tasks.size();i++)try{Scan scan=tasks.get(i).get(Math.max(1,deadline-System.nanoTime()),TimeUnit.NANOSECONDS);available.add(scan.root);for(Match m:scan.matches)if(canonical.add(m.folder.toLowerCase(Locale.ROOT)+"|"+m.root.factory.toLowerCase(Locale.ROOT)))found.add(m);}catch(Exception error){tasks.get(i).cancel(true);unavailable.add(roots.get(i).path);if(error instanceof InterruptedException)Thread.currentThread().interrupt();}
  found.sort(Comparator.comparing(m->m.root.factory+" "+m.folder));return new Result(project,List.copyOf(found),List.copyOf(available),List.copyOf(unavailable));
 }
 static boolean factoryHint(String text){return Pattern.compile("(?iu)(?<![\\p{L}])(soest|alphen|veenoord|lelystad|vianen|cascobouw)(?![\\p{L}])").matcher(text).find();}
 static boolean mentionsRoot(Result result,String text){if(factoryHint(text))return true;String lower=text.toLowerCase(Locale.ROOT);return result.choices().stream().anyMatch(m->lower.contains(m.root.path.toLowerCase(Locale.ROOT))||!m.root.factory.isBlank()&&Pattern.compile("(?iu)(?<![\\p{L}])"+Pattern.quote(m.root.factory)+"(?![\\p{L}])").matcher(text).find());}
 static Match explicit(Result result,String text){String lower=text.toLowerCase(Locale.ROOT);List<Match> choices=result.choices().stream().filter(m->lower.contains(m.folder.toLowerCase(Locale.ROOT))&&!m.folder.isBlank()||lower.contains(m.root.path.toLowerCase(Locale.ROOT))||!m.root.factory.isBlank()&&Pattern.compile("(?iu)(?<![\\p{L}])"+Pattern.quote(m.root.factory)+"(?![\\p{L}])").matcher(text).find()).toList();if(choices.size()!=1)return null;Match match=choices.get(0);if(factoryHint(text)&&!match.root.factory.isBlank()&&!Pattern.compile("(?iu)(?<![\\p{L}])"+Pattern.quote(match.root.factory)+"(?![\\p{L}])").matcher(text).find())return null;return match;}
 static String describe(Object config){return Json.write(roots(config).stream().map(root->Json.obj("factory",root.factory,"path",root.path)).toList());}
 static Match selected(Result result,String root,String folder){return result.choices().stream().filter(m->m.root.path.equalsIgnoreCase(root)&&m.folder.equalsIgnoreCase(folder)).findFirst().orElse(null);}
 static Match confirmed(Result result,List<Root> configured,String root,String folder,String factory){
  Match found=selected(result,root,folder);if(found!=null)return found;
  // A disconnected network root does not erase an explicit saved factory choice.
  if(!folder.isBlank()&&!factory.isBlank()&&result.unavailable.stream().anyMatch(p->p.equalsIgnoreCase(root))&&configured.stream().anyMatch(r->r.path.equalsIgnoreCase(root)&&(r.factory.isBlank()||r.factory.equalsIgnoreCase(factory))))return new Match(new Root(factory,root),folder);
  return null;
 }
 static boolean scopeChange(String text){return Pattern.compile("(?iu)\\b(?:schimba|switch|change|wissel|cambia|zmien|degistir)\\s+(?:fabrica|factory|fabriek|destinatia|destination)\\b|\\b(?:proceseaza|lucreaza|continua|continue|muta|process|verwerk|procesa|przetwarzaj|isle)\\s+(?:(?:proiectul|project|proiect)\\s+[0-9]{6}\\s+)?(?:la|in|pentru|for|at|naar|voor|en|dla)\\s+(?:MBS\\s+)?(?:soest|alphen|veenoord|lelystad)\\b").matcher(I18n.romanianAscii(text)).find();}
 static boolean needsName(Result result){return result.choices().size()==1&&result.choices().get(0).root.factory.isBlank();}
 static String factoryName(String value){String clean=value.strip().replaceFirst("(?i)^MBS\\s*","");return clean.toLowerCase(Locale.ROOT);}
 static ComposerAssist.Request question(Result result){if(needsName(result))return new ComposerAssist.Request(I18n.text("Confirma fabrica pentru locatia {0}.",result.choices().get(0).root.path),List.of(new ComposerAssist.Question("factory-name",I18n.text("Care este fabrica proiectului {0}?",result.project),List.of("MBS Soest","MBS Alphen","MBS Veenoord","MBS Lelystad"))),List.of());List<String> labels=new ArrayList<>();int i=0;for(Match m:result.choices())labels.add((++i)+". "+m.label());String message=I18n.text(result.matches.isEmpty()?"Proiectul {0} nu a fost gasit. Alege fabrica pentru continuare.":"Proiectul {0} apare in mai multe locatii. Alege fabrica si folderul.",result.project);if(!result.unavailable.isEmpty())message+="\n"+I18n.text("Locatii neverificate: {0}",String.join(", ",result.unavailable));return new ComposerAssist.Request(message,List.of(new ComposerAssist.Question("factory",I18n.text("Unde procesez proiectul {0}?",result.project),labels)),List.of());}
 static Match answer(Result result,String answer){var candidates=result.choices();List<Match> matches=new ArrayList<>();for(int i=0;i<candidates.size();i++){Match m=candidates.get(i);if(answer.equals((i+1)+". "+m.label())||answer.equalsIgnoreCase(m.folder)&&!m.folder.isBlank()||answer.equalsIgnoreCase(m.root.path)||!m.root.factory.isBlank()&&answer.equalsIgnoreCase(m.root.factory))matches.add(m);}return matches.size()==1?matches.get(0):null;}
 private ProjectLocations(){}
}
